import { For, Show, createEffect, createSignal, onCleanup, onMount, splitProps, type Accessor, type JSX } from 'solid-js';
import { Portal, isServer } from 'solid-js/web';
import {
	SONNER_DEFAULT_DURATION,
	buildSonnerToastApi,
	createSonnerStore,
	getSonnerPositionStyleKeys,
	resolveSonnerTheme,
	sonnerStyleKeys,
	type SonnerPosition,
	type SonnerStore,
	type SonnerTheme,
	type SonnerToast,
	type SonnerToastApi,
	type SonnerToasterBaseProps,
	type SonnerType,
} from '../lib/core';
import { createExternalStoreAccessor } from '../lib/utils';
import styles from './sonner.module.scss';

const positions: SonnerPosition[] = ['top-left', 'top-center', 'top-right', 'bottom-left', 'bottom-center', 'bottom-right'];
const emptyToasts: SonnerToast[] = Object.freeze([]) as unknown as SonnerToast[];
const toasterOwners = new Map<symbol, number | undefined>();
const [activeToasterOwner, setActiveToasterOwner] = createSignal<symbol>();
let browserStore: SonnerStore | undefined;

function getBrowserStore(): SonnerStore | undefined {
	if (isServer) return undefined;
	return (browserStore ??= createSonnerStore());
}

const storeFacade: SonnerStore = {
	getToasts: () => getBrowserStore()?.getToasts() ?? emptyToasts,
	subscribe: (listener) => getBrowserStore()?.subscribe(listener) ?? (() => undefined),
	add: (input) => getBrowserStore()?.add(input) ?? '',
	update: (id, patch) => getBrowserStore()?.update(id, patch),
	dismiss: (id) => getBrowserStore()?.dismiss(id),
	remove: (id) => getBrowserStore()?.remove(id),
	dismissAll: () => getBrowserStore()?.dismissAll(),
	setDefaultDuration: (duration) => getBrowserStore()?.setDefaultDuration(duration),
};

export const toast: SonnerToastApi = buildSonnerToastApi(storeFacade);

export interface UseToastReturn {
	toasts: Accessor<SonnerToast[]>;
	toast: SonnerToastApi;
	dismiss: (id?: string) => void;
	dismissAll: () => void;
}

export function useToast(): UseToastReturn {
	const toasts = createExternalStoreAccessor(
		() => {
			const store = getBrowserStore()!;
			return { getSnapshot: store.getToasts, subscribe: store.subscribe };
		},
		{ serverSnapshot: emptyToasts },
	);
	return {
		toasts,
		toast,
		dismiss: (id) => toast.dismiss(id),
		dismissAll: () => toast.dismissAll(),
	};
}

function applyDefaultDuration() {
	const owners = Array.from(toasterOwners.entries());
	setActiveToasterOwner(owners.at(-1)?.[0]);
	getBrowserStore()?.setDefaultDuration(owners.at(-1)?.[1] ?? SONNER_DEFAULT_DURATION);
}

function svg(children: JSX.Element) {
	return (
		<svg
			xmlns="http://www.w3.org/2000/svg"
			width="16"
			height="16"
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			stroke-width="2"
			stroke-linecap="round"
			stroke-linejoin="round"
			aria-hidden="true">
			{children}
		</svg>
	);
}

function ToastIcon(props: { type: SonnerType }) {
	switch (props.type) {
		case 'success':
			return svg(
				<>
					<circle cx="12" cy="12" r="10" />
					<path d="m9 12 2 2 4-4" />
				</>,
			);
		case 'info':
			return svg(
				<>
					<circle cx="12" cy="12" r="10" />
					<path d="M12 16v-4" />
					<path d="M12 8h.01" />
				</>,
			);
		case 'warning':
			return svg(
				<>
					<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z" />
					<path d="M12 9v4" />
					<path d="M12 17h.01" />
				</>,
			);
		case 'error':
			return svg(<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8Z" />);
		case 'loading':
			return svg(<path d="M21 12a9 9 0 1 1-6.219-8.56" />);
		default:
			return null;
	}
}

function CloseIcon() {
	return svg(
		<>
			<path d="M18 6 6 18" />
			<path d="m6 6 12 12" />
		</>,
	);
}

function toastRole(type: SonnerType): 'alert' | 'status' {
	return type === 'error' || type === 'warning' ? 'alert' : 'status';
}

export interface ToasterProps extends Omit<JSX.HTMLAttributes<HTMLDivElement>, 'children'>, SonnerToasterBaseProps {}

/** SolidJS Toaster：服务端保持为空，浏览器挂载后订阅单例队列并渲染固定位置容器。 */
export function Toaster(props: ToasterProps) {
	const [local, rest] = splitProps(props, ['class', 'position', 'duration', 'theme', 'richColors', 'closeButton']);
	const toasts = useToast().toasts;
	const [prefersDark, setPrefersDark] = createSignal(false);
	const durationOwner = Symbol('sonner-toaster-duration');

	onMount(() => {
		toasterOwners.set(durationOwner, local.duration);
		applyDefaultDuration();
		createEffect(() => {
			toasterOwners.set(durationOwner, local.duration);
			applyDefaultDuration();
		});
		onCleanup(() => {
			toasterOwners.delete(durationOwner);
			applyDefaultDuration();
		});
	});

	createEffect(() => {
		if (local.theme !== 'system' || isServer || typeof window.matchMedia !== 'function') return;
		const media = window.matchMedia('(prefers-color-scheme: dark)');
		const update = () => setPrefersDark(media.matches);
		update();
		media.addEventListener('change', update);
		onCleanup(() => media.removeEventListener('change', update));
	});

	const resolvedTheme = () => resolveSonnerTheme(local.theme as SonnerTheme | undefined, prefersDark());
	const positionToasts = (position: SonnerPosition) => toasts().filter((item) => (item.position ?? local.position ?? 'bottom-right') === position);
	const lanes = (
		<For each={positions}>
			{(position) => {
				const styleKeys = getSonnerPositionStyleKeys(position);
				const list = () => positionToasts(position);
				return (
					<div
						data-slot="toaster"
						data-position={position}
						data-theme={resolvedTheme()}
						data-rich-colors={local.richColors ? 'true' : undefined}
						hidden={list().length === 0}
						class={`${styles[styleKeys.base]} ${styles[styleKeys.position]} ${resolvedTheme() ?? ''}`}>
						<For each={list()}>
							{(item) => (
								<div
									role={toastRole(item.type)}
									aria-live={toastRole(item.type) === 'alert' ? 'assertive' : 'polite'}
									aria-atomic="true"
									data-slot="toast"
									data-type={item.type}
									data-dismissing={item.dismissing ? 'true' : undefined}
									data-rich-colors={item.richColors === undefined ? undefined : item.richColors ? 'true' : 'false'}
									class={styles[sonnerStyleKeys.toast]}>
									<Show when={item.type !== 'default'}>
										<div class={styles[sonnerStyleKeys.icon]}>
											<ToastIcon type={item.type} />
										</div>
									</Show>
									<div class={styles[sonnerStyleKeys.content]}>
										<Show when={item.title !== undefined}>
											<div class={styles[sonnerStyleKeys.title]}>{item.title}</div>
										</Show>
										<Show when={item.description !== undefined}>
											<div class={styles[sonnerStyleKeys.description]}>{item.description}</div>
										</Show>
									</div>
									<Show when={(local.closeButton ?? true) && item.dismissible !== false}>
										<button type="button" aria-label="关闭" class={styles[sonnerStyleKeys.close]} onClick={() => toast.dismiss(item.id)}>
											<CloseIcon />
										</button>
									</Show>
								</div>
							)}
						</For>
					</div>
				);
			}}
		</For>
	);

	return (
		<div {...rest} data-slot="toaster-root" data-theme={resolvedTheme()} class={local.class}>
			{isServer || activeToasterOwner() !== durationOwner ? null : <Portal>{lanes}</Portal>}
		</div>
	);
}

export default Toaster;

@use '../../../styles/variables/colors' as *;

// Toaster 容器
.root {
	position: fixed;
	z-index: $z-modal;
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	width: max-content;
	max-width: calc(100vw - 2rem);
	pointer-events: none;

	&.positionTopLeft {
		top: $spacing-4;
		left: $spacing-4;
	}

	&.positionTopRight {
		top: $spacing-4;
		right: $spacing-4;
	}

	&.positionTopCenter {
		top: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}

	&.positionBottomLeft {
		bottom: $spacing-4;
		left: $spacing-4;
	}

	&.positionBottomRight {
		right: $spacing-4;
		bottom: $spacing-4;
	}

	&.positionBottomCenter {
		bottom: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}
}

// 单条提示
.toast {
	display: flex;
	align-items: center;
	gap: $spacing-3;
	min-width: 0;
	border: 1px solid var(--tile-toast-border, $border);
	border-radius: var(--tile-toast-radius, $radius);
	background-color: var(--tile-toast-background, $popover);
	color: $popover-foreground;
	padding: var(--tile-toast-padding, $spacing-3 $spacing-4);
	box-shadow: var(--tile-toast-shadow, $shadow-md);
	outline: var(--tile-toast-outline, none);
	pointer-events: auto;
	transition:
		opacity $transition-normal,
		transform $transition-normal;

	&[data-dismissing='true'] {
		opacity: 0;
		transform: translateY(0.5rem);
	}

	// Optional status surfaces and rings can style titles independently.
	// Unset tokens leave Tile's regular (non-rich) toast untouched.
	@each $type in success, info, warning, error {
		&[data-type='#{$type}'] {
			background-color: var(--tile-toast-#{$type}-background, var(--tile-toast-background, $popover));
			outline: var(--tile-toast-#{$type}-outline, var(--tile-toast-outline, none));

			.title {
				color: var(--tile-toast-#{$type}-title-color, inherit);
			}
		}
	}
}

// 图标
.icon {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	width: $spacing-5;
	height: $spacing-5;

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}

	.toast[data-type='success'] & {
		color: var(--tile-toast-success-color, $success);
	}

	.toast[data-type='info'] & {
		color: var(--tile-toast-info-color, $info);
	}

	.toast[data-type='warning'] & {
		color: var(--tile-toast-warning-color, $warning);
	}

	.toast[data-type='error'] & {
		color: var(--tile-toast-error-color, $destructive);
	}
}

// 内容
.content {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
}

// 标题
.title {
	font-size: var(--tile-toast-title-size, $text-sm);
	font-weight: $font-medium;
	line-height: var(--tile-toast-title-leading, $leading-tight);
}

// 描述
.description {
	margin-top: 0.125rem;
	font-size: var(--tile-toast-description-size, $text-sm);
	color: var(--tile-toast-description-color, $muted-foreground);
	line-height: var(--tile-toast-description-leading, $leading-normal);
}

// 富色模式：按类型着色整条提示
.root[data-rich-colors='true'] {
	.toast:not([data-rich-colors='false']) {
		border-color: transparent;

		&[data-type='success'] {
			background-color: var(--tile-toast-success-background, $success);
			color: var(--tile-toast-rich-color, $success-foreground);

			.icon {
				color: var(--tile-toast-success-color, $success-foreground);
			}
		}

		&[data-type='info'] {
			background-color: var(--tile-toast-info-background, $info);
			color: var(--tile-toast-rich-color, $info-foreground);

			.icon {
				color: var(--tile-toast-info-color, $info-foreground);
			}
		}

		&[data-type='warning'] {
			background-color: var(--tile-toast-warning-background, $warning);
			color: var(--tile-toast-rich-color, $warning-foreground);

			.icon {
				color: var(--tile-toast-warning-color, $warning-foreground);
			}
		}

		&[data-type='error'] {
			background-color: var(--tile-toast-error-background, $destructive);
			color: var(--tile-toast-rich-color, $destructive-foreground);

			.icon {
				color: var(--tile-toast-error-color, $destructive-foreground);
			}
		}
	}
}

.toast[data-rich-colors='true'] {
	border-color: transparent;

	&[data-type='success'] {
		background-color: var(--tile-toast-success-background, $success);
		color: var(--tile-toast-rich-color, $success-foreground);

		.icon {
			color: var(--tile-toast-success-color, $success-foreground);
		}
	}

	&[data-type='info'] {
		background-color: var(--tile-toast-info-background, $info);
		color: var(--tile-toast-rich-color, $info-foreground);

		.icon {
			color: var(--tile-toast-info-color, $info-foreground);
		}
	}

	&[data-type='warning'] {
		background-color: var(--tile-toast-warning-background, $warning);
		color: var(--tile-toast-rich-color, $warning-foreground);

		.icon {
			color: var(--tile-toast-warning-color, $warning-foreground);
		}
	}

	&[data-type='error'] {
		background-color: var(--tile-toast-error-background, $destructive);
		color: var(--tile-toast-rich-color, $destructive-foreground);

		.icon {
			color: var(--tile-toast-error-color, $destructive-foreground);
		}
	}
}

.root[data-rich-colors='true'] .toast:not([data-rich-colors='false']),
.toast[data-rich-colors='true'] {
	.description,
	.close,
	.close:hover {
		color: var(--tile-toast-rich-description-color, inherit);
	}
}

// 关闭按钮
.close {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: var(--tile-toast-close-radius, $radius);
	background: transparent;
	color: $muted-foreground;
	cursor: pointer;
	padding: $spacing-1;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&:hover {
		background-color: var(--tile-toast-close-hover-background, $muted);
		color: $foreground;
	}

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}
}

// 操作按钮容器
.actions {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-1;
}
